+ '</div>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> numpy <span class="kw">as</span> np\n\n<span class="cm"># === Batch Matrix Multiply (3-D) ===</span>\n<span class="cm"># 10 matrices of shape (3,4) times 10 matrices of shape (4,5)</span>\nbatch_A = np.random.<span class="fn">randn</span>(<span class="num">10</span>, <span class="num">3</span>, <span class="num">4</span>)\nbatch_B = np.random.<span class="fn">randn</span>(<span class="num">10</span>, <span class="num">4</span>, <span class="num">5</span>)\nbatch_C = batch_A @ batch_B  <span class="cm"># (10, 3, 5) \u2014 each matrix multiplied independently</span>\n\n<span class="cm"># === Matrix-Vector Product ===</span>\nW = np.random.<span class="fn">randn</span>(<span class="num">3</span>, <span class="num">4</span>)   <span class="cm"># weight matrix</span>\nx = np.random.<span class="fn">randn</span>(<span class="num">4</span>)       <span class="cm"># input vector</span>\noutput = W @ x               <span class="cm"># (3,)  \u2014 this IS a neural network layer!</span>\n\n<span class="cm"># === np.dot vs @ for higher dimensions ===</span>\n<span class="cm"># np.dot: sums over LAST axis of A and SECOND-TO-LAST of B</span>\n<span class="cm"># np.matmul/@: treats last 2 dims as matrices, broadcasts the rest</span>\n<span class="cm"># For 2-D arrays, they are identical. For 3-D+, prefer @/matmul.</span></code></pre></div>'

