+ '<div class="calc-card"><div class="card-title">np.linalg.cond</div><div class="card-body">Condition number: ratio of largest to smallest singular value. High \u03ba means small input changes cause large output changes. Indicates numerical instability.</div></div>'
+ '</div>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> numpy <span class="kw">as</span> np\n\n<span class="cm"># === Determinant ===</span>\nA = np.<span class="fn">array</span>([[<span class="num">3</span>, <span class="num">1</span>],\n              [<span class="num">2</span>, <span class="num">4</span>]])\n<span class="fn">print</span>(np.linalg.<span class="fn">det</span>(A))    <span class="cm"># 10.0  (3*4 - 1*2)</span>\n\n<span class="cm"># Singular matrix (det = 0)</span>\nS = np.<span class="fn">array</span>([[<span class="num">1</span>, <span class="num">2</span>],\n              [<span class="num">2</span>, <span class="num">4</span>]])   <span class="cm"># row 2 = 2 * row 1</span>\n<span class="fn">print</span>(np.linalg.<span class="fn">det</span>(S))    <span class="cm"># 0.0  \u2192 NOT invertible!</span>\n\n<span class="cm"># === Rank ===</span>\n<span class="fn">print</span>(np.linalg.<span class="fn">matrix_rank</span>(A))  <span class="cm"># 2 (full rank)</span>\n<span class="fn">print</span>(np.linalg.<span class="fn">matrix_rank</span>(S))  <span class="cm"># 1 (rank-deficient)</span>\n\n<span class="cm"># === Trace ===</span>\n<span class="fn">print</span>(np.<span class="fn">trace</span>(A))           <span class="cm"># 7  (3 + 4)</span>\n\n<span class="cm"># === Inverse ===</span>\nA_inv = np.linalg.<span class="fn">inv</span>(A)\n<span class="fn">print</span>(A_inv)\n<span class="cm"># [[ 0.4 -0.1]</span>\n<span class="cm">#  [-0.2  0.3]]</span>\n<span class="fn">print</span>(A @ A_inv)  <span class="cm"># identity matrix (within float precision)</span>\n\n<span class="cm"># === Condition Number ===</span>\n<span class="fn">print</span>(np.linalg.<span class="fn">cond</span>(A))     <span class="cm"># ~3.24  (well-conditioned)</span>\n\n<span class="cm"># Ill-conditioned matrix</span>\nill = np.<span class="fn">array</span>([[<span class="num">1</span>, <span class="num">1</span>],\n                [<span class="num">1</span>, <span class="num">1.0001</span>]])\n<span class="fn">print</span>(np.linalg.<span class="fn">cond</span>(ill))   <span class="cm"># ~40000  (numerically unstable!)</span></code></pre></div>'

